function ledForm(s) { const j = s.jobs || []; return j.every(x => x === 'sec' || x === 'info') ? 'sec' : j.includes('sec') ? 'mix' : 'etc'; }
const LED_FORM_N = { sec: '보안 양식 (사업지원서비스업)', etc: '시설·미화·기타 양식 (시설관리 및 조경서비스업 외)', mix: '미화·시설 + 보안 포함 양식' };
