  const base = /시스템/.test(nm) ? LED_COS.sys : (!nm || /베스트/.test(nm) || s.org === 'best') ? LED_COS.best : { n: /^주식회사/.test(nm) ? nm : '주식회사 ' + nm, ceo: '', addr: '', biz: '사업시설관리 및 사업지원서비스업' };
  info = info || {};
