  if (it.id === '1-7') { if (f !== 'sec' && n >= 20 && n < 50) { v = 'o'; why = `상시근로자 ${n}명(20~49인)`; } else { v = 'n'; why = n >= 50 ? '50인 이상 — 안전·보건관리자 선임 사업장' : f === 'sec' ? '보안 양식 해당 없음' : `상시근로자 ${n || '-'}명 — 20인 이상만 지정`; } }
  if (it.id === '2-5') { if (f === 'sec') { v = 'n'; } else if (hasJ(s, 'fac') || (info.special || []).length) { v = 'o'; why = '시설 작업(밀폐공간 · 고소 · 전기 등) 해당'; } else { v = 'c'; why = '1~39호 해당 작업을 할 때만'; } }
